window.DGNL_DE_MON["l12"] = {"id": "l12", "ten": "Đề thi thử số 12", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Cậu ấy vẫn còn ______ trước quyết định quan trọng này<br>Từ nào phù hợp nhất để điền vào chỗ trống?", "choices": ["e ấp", "e lệ", "e dè", "e thẹn"], "correctIndex": 2, "explain": "Câu 1: C.<b> </b>e dè (Thái độ ngần ngại, không tự tin trước một việc gì đó. E ấp, e lệ, e thẹn thường dùng cho sắc thái tình cảm thiếu nữ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu không mắc lỗi chính tả", "choices": ["Đến ngã ba, anh dừng lại một lúc như thể đang phân vân trước mỗi ngã đường của cuộc đời.", "Nó lửng thửng bước đi, dường như vẫn còn suy nghĩ về câu chuyện lúc nãy.", "Cô ấy không cố ý, chỉ vì quen cách ăn nói lửng khửng nên dễ gây hiểu lầm.", "Anh lặng nhìn những ngọn khói lơ lững trên tầng không."], "correctIndex": 2, "explain": "<b>Câu 2: C.</b> (Câu A sai &quot;ngã đường&quot; -&gt; <i>ngả đường</i>; B sai &quot;lửng thửng&quot; -&gt; <i>lững thững</i>; D sai &quot;lơ lững&quot; -&gt; <i>lơ lửng</i>)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Ngẩng lên đã tới nhà má. Lý vẫn thường đi về nhà bằng kiểu đó những lúc tan hoang. Không biết đi cách nào, bao lâu, bằng gì, chỉ biết sực tỉnh nhìn quanh là cái bàn ông thiên nằm giữa bụi bông trang đỏ hiện ra. Hai chân về nhà luôn có mắt. Nuốt ực bao nhiêu đau đớn bên cái cổng rào ọp ẹp, như mọi khi, chị làm mặt tỉnh bước vào.</i><br><i>- Qua cơn khùng rồi sao?</i><br><i>Má hỏi khi vừa nhìn thấy Lý. Mình cũng gây chuyện ở đây, chị nghĩ. Mớ rau muống đỏ eng lả ngọn trong thúng. </i>(Sổ lồng, Nguyễn Ngọc Tư)<br>Đâu không phải là tác dụng của việc sử dụng khẩu ngữ trong trích đoạn trên?", "choices": ["Làm cho lời văn trở nên tự nhiên, gần với lời ăn tiếng nói hằng ngày.", "Góp phần khắc họa tính cách nhân vật mộc mạc, thẳng thắn.", "Tạo sắc thái chân thực, giúp không khí truyện gần gũi với đời sống.", "Góp phần làm nổi bật xung đột giữ má và Lý."], "correctIndex": 3, "explain": "<b>Câu 3: D.</b> (Khẩu ngữ như &quot;má&quot;, &quot;qua cơn khùng&quot;, &quot;nuốt ực&quot; giúp văn bản gần gũi, khắc họa tính cách mộc mạc chứ không phải để đẩy cao xung đột)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Chọn câu đúng</b>", "choices": ["Trong hai lượt bơi của Minh đều về chót.", "Thư viện là không gian học tập của nhiều đối tượng khác nhau như học sinh, sinh viên, giáo viên,… thậm chí có cả những người đã đi làm và người lớn tuổi đến tìm kiếm tri thức.", "Với nó trong những buổi trưa nắng cháy trên cánh đồng lúa chín, ở miền quê xa xôi có dòng sông uốn lượn.", "Hơn nửa đời lí nhí cúi mặt, Lý bỗng nhìn thẳng vào trời không run sợ mảy may."], "correctIndex": 3, "explain": "Câu 4: D. (Câu A thiếu chủ ngữ/sai cấu trúc; B lạm dụng từ &quot;thậm chí&quot; và liệt kê chưa chuẩn; C là câu thiếu vị ngữ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Chọn phương án chứa yếu tố “thất” mang nét nghĩa khác các phương án còn lại.</b>", "choices": ["Gặp cảnh thất cơ lỡ vận, gia đình cậu bỗng trở nên đoàn kết hơn bao giờ hết.", "Người bản lĩnh không thất chí trước những gièm pha, dị nghị.", "Thất tín với khách hàng là điều tối kị mà một doanh nghiệp cần tránh.", "Dáng đi thất thểu của anh ấy cho chúng tôi biết hôm nay anh đã yếu đi nhiều."], "correctIndex": 3, "explain": "<b>Câu 5: D.</b> <b>thất thểu</b> (Yếu tố &quot;thất&quot; ở đây là từ láy mô phỏng dáng đi. Các từ còn lại: <i>thất cơ, thất chí, thất tín</i> đều có nghĩa là &quot;mất&quot; hoặc &quot;không có&quot;)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Chọn phương án chứa từ “đồng” mang nghĩa khác các phương án còn lại</b>", "choices": ["Những kỉ niệm cùng bạn đồng ấu bên bờ sông vẫn luôn là phần trong trẻo nhất trong tâm trí anh.", "Những câu chuyện đồng thoại giúp nuôi dưỡng trí tưởng tượng và tâm hồn trẻ thơ.", "Trong lúc khó khăn, tinh thần tương trợ giữa đồng bào càng trở nên rõ nét.", "Tết năm nay, đại gia đình tứ đại đồng đường quây quần đông đủ bên mâm cơm."], "correctIndex": 1, "explain": "Câu 6: B. đồng thoại (&quot;Đồng&quot; ở đây là trẻ em/nhi đồng. Các từ còn lại: đồng ấu (cùng thời thơ ấu), đồng bào (cùng bọc), đồng đường (cùng nhà) đều mang nghĩa là &quot;cùng&quot;)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Qua từng tháng năm dạy học tận tuỵ, các học trò càng yêu mến người giáo viên ấy.<br>Câu trên mắc lỗi gì?", "choices": ["Sai quy chiếu", "Lỗi mơ hồ", "Lỗi ngữ pháp", "Lỗi dùng từ"], "correctIndex": 0, "explain": "<b>Câu 7. Lỗi quy chiếu (Đáp án A)</b><br><b>Phân tích: Cấu trúc câu có dạng <i>[Cụm hành động đứng đầu câu], [Chủ ngữ] + [Vị ngữ]</i>. Trong tiếng Việt, hành động ở đầu câu mặc định phải thuộc về chủ ngữ của vế sau.</b><br><b>Điểm sai: Cụm &quot;dạy học tận tụy&quot; đang bị hiểu lầm là hành động của &quot;các học trò&quot; (chủ ngữ vế chính). Tuy nhiên, về logic, học trò không thể dạy học.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Trong khoảnh khắc im lặng kéo dài đến ngột ngạt ấy, anh <b>dường như</b> nhận ra rằng những điều mình từng tin tưởng bấy lâu hóa ra chỉ là ảo tưởng được dựng lên bởi chính nỗi sợ hãi của bản thân.<br>Thành phần được in đậm là thành phần gì?", "choices": ["Thành phần tình thái", "Thành phần phụ chú", "Thành phần gọi đáp", "Thành phần cảm thán"], "correctIndex": 0, "explain": "<b>Câu 8: A. Thành phần tình thái (&quot;dường như&quot; thể hiện độ tin cậy của người nói đối với sự việc).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>Xuân cảnh<br>(Trần Nhân Tông)<br>Dương liễu hoa thâm điểu ngữ trì,<br>Hoạ đường thiềm ảnh mộ vân phi.<br>Khách lai bất vấn nhân gian sự,<br>Cộng ỷ lan can khán thuý vi.<br>Dịch nghĩa<br>Trong khóm hoa dương liễu rậm, chim hót chậm rãi,<br>Dưới bóng thềm ngôi nhà chạm vẽ, mây chiều lướt bay.<br>Khách đến chơi không hỏi việc đời,<br>Cùng đứng tựa lan can ngắm màu xanh mờ mịt ở chân trời.<br>Tâm trạng của chủ thể trữ tình trong bài thơ trên là gì?", "choices": ["Buồn bã, cô đơn trước cảnh thiên nhiên vắng lặng.", "Thanh thản, ung dung, tạm quên đi những lo toan của cuộc sống.", "Bâng khuâng, tiếc nuối trước sự trôi chảy của thời gian.", "Trăn trở, suy tư về những biến động của nhân gian."], "correctIndex": 1, "explain": "<b>Câu 9: B.</b> (Bài thơ thể hiện phong thái tự tại, thoát tục của vị vua thi sĩ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i><b>“</i></b><i>Nữ thần Demeter tìm con gái khắp nơi mà không thấy. Sau cùng quá mệt mỏi và thất vọng thần quay về Sicily, và đứng bên dòng sông Cyane, đúng chỗ thần Pluto xẻ đất. để xuống cõi âm. Một nữ thủy thần đã nhìn thấy thần Pluto cùng nàng Persephone muốn mách nữ thần Demeter nhưng lại sợ nên đành câm nín. Trước đây nàng đã nhặt được sợi dây lưng của Persephone bèn gửi sóng đưa đẩy tới chân nữ thần Demeter. Bấy giờ nữ thần mới chắc là con gái mình đã mất tích thực, nhưng vẫn không ngờ thần Pluto đánh cắp con. Chẳng biết sao nữ thần lại giận mặt đất vô tội.</i><br><i>Nữ thần nói :</i><br><i>- Hỡi đất vô ơn ! Ta làm cho ngươi phì nhiêu, ta may áo bằng cỏ và hạt ngũ cốc cho ngươi, vậy mà giờ đây ngươi đối xử với ta như vậy đó – ngươi đừng hòng ta ban ơn cho nữa !</i><br><i>Năm đó thật là một năm kinh hoàng. Cây cối không đâm chồi nảy lộc, súc vật chết, hạt giống không nảy mầm, người và trâu bò làm việc vô hiệu.”</i><br>(Doãn Quốc Sỹ)<br>Đây là trích đoạn trong văn bản thuộc thể loại gì?", "choices": ["Sử thi", "Thần thoại", "Truyện viễn tưởng", "Truyền thuyết."], "correctIndex": 1, "explain": "<b>Câu 10: B. Thần thoại (Kể về các vị thần Hy Lạp như Demeter, Pluto và giải thích hiện tượng thiên nhiên).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>LÊ TƯƠNG DỰC - à mi giỏi thực! Lần này trẫm không tha mi nữa, trẫm cũng không cần mi nữa, (xem quyển sổ) đủ rồi. Đủ rồi, trẫm gọi thợ khác cứ theo đây mà xây, sửa chút ít là vừa ý trẫm. Còn mi, mi chờ quân đao phủ dẫn đi.</i><br><i>VŨ NHƯ TÔ - Đó là quyền Hoàng thượng. Nhưng.. xây đài Cửu trùng không dễ thế đâu. Nếu chỉ xem sách mà làm được thì chán nhà nho đã thành Khổng Tử, chán vị tướng đã thành Tôn, Ngô, chán thi nhân đã thành Lý, Đỗ. Cần phải có mắt, có tai, có tâm huyết, có tay mình vào đó. Hoàng thượng cứ giữ lấy bản đồ, cầm lấy quyển sổ, đi tìm thợ giỏi, tiện nhân không dám nói sao, nhưng tiện nhân tin rằng không một kẻ nào làm nổi. Bản đồ kia chỉ là phần xác, nhưng phần hồn thì chỉ ở lòng tiện nhân, mà phần hồn mới là phần chính.</i><br><i>(Vũ Như Tô, Nguyễn Huy Tưởng)</i><br>Đâu là nhận định phù hợp nhất về nhân vật Vũ Như Tô trong đoạn trích?", "choices": ["Ý thức rõ giá trị sáng tạo cá nhân, có xu hướng tách khỏi thực tế.", "Dốc toàn bộ tâm huyết cho công trình, xem đó là lí tưởng sống.", "Thừa nhận quyền lực nhưng kiên quyết bảo vệ quan niệm nghệ thuật.", "Coi trọng “phần hồn” của công trình, xem đó là yếu tố quyết định."], "correctIndex": 3, "explain": "<b>Câu 11: D.</b> (Vũ Như Tô nhấn mạnh: &quot;phần hồn mới là phần chính&quot; và chỉ ông mới nắm giữ được nó)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>“</b>Kiến đậu cành cam bò quấn quýt/Ngựa về làng Bưởi chạy lanh chanh” (Dân gian Việt Nam)<br>Hai câu trên không sử dụng biện pháp tu từ nào?", "choices": ["Chơi chữ", "Đối", "Lặp cấu trúc", "Điệp ngữ"], "correctIndex": 3, "explain": "<b>Câu 12: D. Điệp ngữ (Có đối, có chơi chữ &quot;cam/Bưởi&quot;, có lặp cấu trúc nhưng không có từ ngữ nào được lặp lại nhằm mục đích tu từ).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Ông rằng: “</i><b><i>Bỉ thử nhất thì</i></b><i>,</i><br><i>Tu hành thì cũng phải khi tòng quyền.</i><br><i>Phải điều cầu Phật cầu tiên,</i><br><i>Tình kia, hiếu nọ, ai đền cho đây?” </i>(Truyện Kiều, Nguyễn Du)<br>Cụm từ in đậm có nghĩa là gì?", "choices": ["Người này người kia đều như nhau trong mọi hoàn cảnh.", "Việc bên này việc bên kia đều quan trọng như nhau.", "Lúc này lúc khác, mỗi thời mỗi cảnh có cách xử lí khác nhau.", "Mọi việc khó đang diễn ra trong cùng một thời điểm."], "correctIndex": 2, "explain": "<b>Câu 13: C.</b> (Bỉ thử nhất thì: Lúc này lúc khác, cần linh hoạt theo hoàn cảnh)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Mười sáu người đủ hàng lớn bé, trẻ già này, mỗi người chỉ cầu như một con chó, nhiều khi kém một con chó, mà lại còn đem chân tay ra làm nhiều việc có ích, rất nặng nhọc, mà vẫn không kiếm được việc.</i><br><i>Tôi chỉ bọn trẻ, trai và gái chưa qua 12 tuổi và hỏi mụ già:</i><br><i>- Cái bọn này thì bà định kiếm cho chúng mỗi tháng độ bao nhiêu công?</i><br><i>Mụ già khinh khỉnh nhìn tôi từ đầu đến chân rồi quay đi chỗ khác. Mãi mới đáp:</i><br><i>- Thời buổi này, bọn nhãi nhép ấy cứ được người ta mượn cơm không thôi là đã phúc!</i><br><i>- Thế thì tiền quà của bà chắc chả mấy..</i><br><i>- Cái đó đã hẳn! Nhưng mà được năm xu một hào thì cũng đủ. Rẻ còn hơn ngồi không..” </i>(Cơm thầy cơm cô, Vũ Trọng Phụng)<br>Đoạn trích trên thể hiện rõ nhất thái độ nào của tác giả?", "choices": ["Cảm thông sâu sắc trước số phận khốn khổ của người lao động nghèo.", "Phê phán gay gắt sự bóc lột và vô cảm của con người trong xã hội.", "Lên án sự bất công trong việc phân chia lao động và vấn đề tiền công.", "Thể hiện sự bất bình trước hoàn cảnh khó khăn của trẻ em."], "correctIndex": 1, "explain": "<b>Câu 14: B.</b> (Bút pháp hiện thực của Vũ Trọng Phụng phơi bày sự rẻ rúng của giá trị con người trong xã hội cũ)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đầu lòng hai ả tố nga,<br>Thúy Kiều là chị em là Thúy Vân<br>Mai cốt cách tuyết tinh thần<br>Mỗi người một vẻ mười phân vẹn mười” (Truyện Kiều, Nguyễn Du)<br>Chữ “Vân” hiệp vần với chữ nào?", "choices": ["thần", "phân", "tinh", "mười"], "correctIndex": 0, "explain": "<b>Giải thích câu 15 (Đáp án A)</b><br><b>Luật thơ: Trong thể lục bát, chữ thứ 8 của câu bát phải hiệp vần với chữ thứ 6 của câu lục tiếp theo.</b><br><b>Thực tế văn bản: Chữ &quot;Vân&quot; (chữ thứ 8 của câu bát: <i>Thúy Kiều là chị em là Thúy Vân</i>) hiệp vần với chữ &quot;thần&quot; (chữ thứ 6 của câu lục tiếp theo: <i>Mai cốt cách tuyết tinh thần</i>).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Đâu là kết cấu cốt truyện thường thấy của truyện thơ Nôm?</b>", "choices": ["Đoàn tụ - Tai biến - Hội ngộ", "Gặp gỡ - Tai biến – Đoàn tụ", "Thề nguyền – Tai biến – Tái hợp", "Tai biến – Đoàn tụ - Hợp hôn"], "correctIndex": 1, "explain": "<b>Giải thích câu 16 (Đáp án B)</b><br><b>Đặc điểm thể loại: Truyện thơ Nôm (như <i>Truyện Kiều, Lục Vân Tiên, Phan Trần</i>...) thường xây dựng cốt truyện theo một mô hình truyền thống phản ánh quan niệm về sự công bằng và hạnh phúc viên mãn.</b><br><b>Cấu trúc 3 chặng:</b><br>1. <b>Gặp gỡ: Giới thiệu gia cảnh, tài năng của nhân vật và cuộc hội ngộ định mệnh, thề nguyền đính ước.</b><br>2. <b>Tai biến: Nhân vật chính gặp biến cố (bị hãm hại, chia lìa, lưu lạc), phải trải qua gian khổ để thử thách lòng trung trinh.</b><br>3. <b>Đoàn tụ: Sau bao sóng gió, các nhân vật tìm lại được nhau, công lý được thực thi, kẻ ác bị trừng trị, người hiền hưởng hạnh phúc.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<b>Đâu không phải là thể loại tự sự dân gian?</b>", "choices": ["Truyền thuyết", "Truyện cổ tích", "Truyện truyền kì", "Truyện cười"], "correctIndex": 1, "explain": "<b>Giải thích câu 17 (Đáp án B)</b><br><b>Truyện truyền kì là thể loại văn học viết (do các trí thức phong kiến sáng tác, tiêu biểu như <i>Truyền kì mạn lục</i> của Nguyễn Dữ). Dù có yếu tố kỳ ảo giống truyện dân gian, nhưng nó có tác giả cụ thể và mang đậm dấu ấn cá nhân, khác với các thể loại truyền miệng như Truyền thuyết, Cổ tích, Truyện cười.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Cho chếnh choáng mùi thơm, cho đã đầy ánh sáng,</i><br><i>Cho no nê thanh sắc của thời tươi;</i><br><i>- Hỡi xuân hồng, ta muốn cắn vào ngươi!</i><br>(Vội vàng, Xuân Diệu)<br>Đâu không phải là tác dụng của việc sử dụng động từ “cắn” trong đoạn thơ trên?", "choices": ["Diễn tả khát khao mãnh liệt muốn tận hưởng trọn vẹn vẻ đẹp của mùa xuân.", "Thể hiện cảm xúc yêu đời cuồng nhiệt, sống vội vàng để chiếm lĩnh thời gian.", "Gợi cảm giác cụ thể hóa cái trừu tượng, làm cho mùa xuân trở nên hữu hình.", "Nhấn mạnh sự tiếc nuối, bất lực trước sự trôi chảy không thể níu giữ của thời gian."], "correctIndex": 3, "explain": "<b>Câu 18: D. (Từ &quot;cắn&quot; thể hiện sự vồ vập, tận hưởng một cách hữu hình hóa mùa xuân, không mang nghĩa bất lực).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Chiều xưa có ngọn trúc đào<br>Mùa thu lá rụng bay vào sân em<br>Mùa thu lá rụng êm đềm<br>Như cô với cậu cười duyên dại khờ<br>Bởi vì hai đứa ngây thơ<br>Tình tôi dạo ấy là.. ngơ ngẩn nhìn<br>Thế rồi trăng sáng lung linh<br>Em mười sáu tuổi giận hờn vu vơ<br>Sang năm mười bảy không ngờ<br>Tình tôi nít nhỏ ngồi mơ cũng thừa<br>Tôi mười bảy tuổi buồn chưa<br>Đầu niên học mới dầm mưa cả ngày”<br>(Nguyễn Tất Nhiên, Trúc đào)<br>Chủ thể trữ tình trong đoạn thơ trên là", "choices": ["trúc đào", "em", "tình tôi", "tôi"], "correctIndex": 3, "explain": "<b>Câu 19: D. tôi (Chủ thể trực tiếp xuất hiện qua đại từ &quot;tôi&quot;).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Lam nhung ô! Màu lưng chừng trời;</i><br><i>Xanh nhung ô! Màu phơi nơi nơi.</i><br><i>Vàng phai nằm im ôm non gầy;</i><br><i>Chim yên neo mình ôm xương cây.</i><br>(Bích Khê, Hoàng Hoa)<br>Tác dụng của yếu tố tượng trưng trong đoạn thơ trên là gì?", "choices": ["Tái hiện chân thực bức tranh thiên nhiên với màu sắc cụ thể, rõ ràng.", "Gợi ra thế giới cảm xúc mơ hồ, huyền ảo thông qua sự chuyển hóa giữa các giác quan.", "Nhấn mạnh sự vận động mạnh mẽ của cảnh vật trong không gian.", "Làm nổi bật vẻ đẹp giản dị, gần gũi của thiên nhiên đời thường."], "correctIndex": 1, "explain": "<b>Câu 20: B. (Sử dụng các hình ảnh &quot;lam nhung&quot;, &quot;xanh nhung&quot; - ẩn dụ chuyển đổi cảm giác, gợi sự mơ hồ của trường phái Tượng trưng).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Tư duy không ngừng suy nghĩ</b><br>Nhóm nghiên cứu sinh học tiến hóa của Đại học Hokkaido ở Nhật Bản từng tiến hành một thí nghiệm: Họ theo dõi ba đàn kiến đen để quan sát sự phân công lao động. Ban đầu họ nhận thấy hầu hết kiến trong đàn đều rất siêng năng, tuy nhiên có những con lười biếng. Các nhà sinh vật học gọi những con kiến này là &quot;kiến lười&quot; và đánh dấu chúng.<br>Điều đáng ngạc nhiên là khi nhóm nghiên cứu cắt đứt nguồn thức ăn của đàn kiến, những con kiến siêng năng đó dường như bỗng trở nên hỗn loạn. Ngược lại, những con kiến lười được đánh dấu lại dẫn dắt đàn tìm được nguồn thức ăn mới.<br>Hiệu ứng kiến lười có thể hiểu rằng, những người tưởng như lười biếng lại là người biết tư duy và khôn ngoan hơn cả, không phải cứ mãi chăm chỉ thì sẽ thành công. Ngược lại không chịu tư duy và không tư duy đúng, có chăm chỉ bao nhiêu cũng tầm thường.<br><b>Tư duy môi trường</b><br>Giữa thế kỷ 19, giáo sư tâm lý học người Đức Kurt Koffka đã đề xuất một lý thuyết trường: Môi trường bên ngoài được chia thành hai loại, một là môi trường địa lý (thực tế) và hai là môi trường hành vi (tưởng tượng).<br>Một đêm mùa đông, có người cưỡi ngựa đến trước cửa một quán trọ trong mưa gió. Tuyết tràn ngập khắp các con đường và anh rất vui khi tìm được một nơi trú ẩn như vậy trong đêm tối. Người chủ quán bước ra cửa ngạc nhiên chào người lạ và hỏi anh ta từ đâu đến. Người đàn ông chỉ thẳng về hướng bên ngoài quán trọ. Người chủ quán nghe vậy, kinh hãi nói: &quot;Anh có biết mình đã đi qua hồ Constance không?&quot;. Khi người đàn ông băng qua hồ, anh cứ tưởng đó là đồng cỏ bị bao phủ tuyết. Nếu biết trước sẽ đi qua một cái hồ lớn, anh sẽ khó có đủ can đảm để phi nước đại trên đó.<br>Con người là sản phẩm của môi trường và cách tốt nhất để thay đổi bản thân là luôn đặt mình vào môi trường có thể nuôi dưỡng bạn. Nếu muốn cải thiện khả năng tập trung, hãy cố gắng tạo cho mình một môi trường không bị quấy rầy. Nếu muốn có thái độ tích cực nên tránh xa những thứ khiến bạn trở nên tiêu cực và ngắm nhìn thiên nhiên nhiều hơn. Và nếu không hài lòng bản thân ở hiện tại, hãy bao phủ xung quanh mình bằng những người tài giỏi và nghị lực, để từ đó có môi trường nâng cấp tư duy, tầm nhìn của bản thân.<br>(Trích theo 7 tư duy thay đổi cuộc đời, Bảo Nhiên)", "cauHoi": [{"question": "Trong phần “Tư duy không ngừng suy nghĩ”, thông tin chi tiết nào được nêu ra để làm sáng tỏ vai trò của “kiến lười” khi đàn kiến rơi vào tình huống bất lợi?", "choices": ["Những con kiến lười thường bị các nhà sinh vật học xem là vô dụng.", "Những con kiến siêng năng luôn giữ vai trò dẫn dắt đàn trong mọi hoàn cảnh.", "Khi nguồn thức ăn bị cắt đứt, những con kiến lười lại dẫn dắt đàn tìm được nguồn thức ăn mới.", "Nhóm nghiên cứu chỉ theo dõi một đàn kiến đen trong thời gian ngắn."], "correctIndex": 2, "explain": "<b>Câu 21: C.</b> Khi nguồn thức ăn bị cắt đứt, những con kiến lười lại dẫn dắt đàn tìm được nguồn thức ăn mới."}, {"question": "Văn bản trên được tổ chức theo cách nào?", "choices": ["Phân loại", "Cấu trúc so sánh đối chiếu", "Trật tự thời", "Nêu hiện tượng rồi liệt kê hàng loạt giải pháp theo mức độ quan trọng."], "correctIndex": 0, "explain": "<b>Câu 22: A. Phân loại (Chia thành các mục: Tư duy không ngừng suy nghĩ, Tư duy môi trường).</b>"}, {"question": "Việc kể lại câu chuyện người cưỡi ngựa tưởng hồ Constance là đồng cỏ phủ tuyết có tác dụng gì trong văn bản?", "choices": ["Giúp văn bản chuyển hẳn sang phương thức tự sự, làm mờ đi mục đích cung cấp thông tin.", "Làm nổi bật một luận điểm bằng một tình huống cụ thể, từ đó giúp người đọc dễ hình dung hơn về ảnh hưởng của nhận thức và môi trường.", "Chủ yếu nhằm tạo sự hồi hộp, hấp dẫn như một truyện ngắn.", "Chứng minh rằng con người luôn sai lầm khi hành động trong điều kiện thời tiết xấu."], "correctIndex": 1, "explain": "<b>Câu 23: B.</b> Làm nổi bật luận điểm bằng tình huống cụ thể (về môi trường hành vi/tưởng tượng)."}, {"question": "Theo văn bản, nếu muốn có thái độ tích cực, con người nên làm gì?", "choices": ["Gần gũi với thiên nhiên, lánh xa nguồn năng lượng tiêu cực.", "Chỉ ở bên cạnh những người thành công hơn mình.", "Không tiếp xúc với môi trường bên ngoài để giữ sự ổn định.", "Luôn đặt mình vào những thử thách nguy hiểm để rèn bản lĩnh."], "correctIndex": 0, "explain": "<b>Câu 24: A. Gần gũi với thiên nhiên, lánh xa nguồn năng lượng tiêu cực.</b>"}, {"question": "Đâu là nhận định không phù hợp với nội dung văn bản?", "choices": ["Trong một số tình huống, người biết quan sát và suy nghĩ có thể tìm ra hướng đi hiệu quả hơn người chỉ quen làm việc theo lối cũ.", "Nhận thức của con người về hoàn cảnh sống có thể ảnh hưởng đến cách họ lựa chọn và hành động.", "Việc chủ động tạo dựng môi trường tích cực có vai trò quan trọng trong quá trình hoàn thiện bản thân.", "Môi trường hành vi quan trọng hơn môi trường địa lý."], "correctIndex": 3, "explain": "<b>Câu 25: D.</b> (Văn bản không khẳng định cái nào quan trọng hơn mà chỉ đưa ra định nghĩa và tác động của chúng)."}], "khongXaoTron": true}, {"noiDungChung": "<i>“Nếu biết học hỏi từ quá khứ thì chúng ta hẳn đã tôn trọng thay vì gây chiến tranh với đồng loại; ta sẽ yêu đất nước mình mà không tuyên bố rằng nó tốt đẹp hơn những đất nước khác, yêu nước cả những khi thành công và thất bại, giống như yêu thương con mình; ta sẽ tò mò về văn hóa các nước láng giềng, ham học hỏi và chia sẻ cho nhau những nét riêng tốt đẹp nhất; ta sẽ biết phân biệt ai là người đang phụng sự lẽ phải tự nhiên, ai là kẻ muốn áp đặt bá quyền; ta cũng có thể sẽ học được cách chung sống yên bình và hài hòa. Để thực hiện ước muốn đó, cũng giống như các nước láng giềng, chúng ta cùng phải học về lịch sử. Tuy nhiên, thói thường khiến người ta học lịch sử một cách không đầy đủ và khách quan: chỉ học từ những gì được giữ lại trong trí nhớ tập thể.</i><br><i>Để củng cố khối đoàn kết quốc gia, chúng ta cần những biểu tượng định danh: quốc kỳ, quốc ca, tiêu ngữ. Độc lập – tự do – hạnh phúc là một tiêu ngữ hay và đáng tự hào của Việt Nam. Tiêu ngữ của nước Pháp không có độc lập và hạnh phúc, nhưng có bình đẳng và bác ái, cũng là tiêu ngữ hay. Bên cạnh đó, chúng ta cũng cần những hình ảnh biểu trưng và người hùng dân tộc, đại diện cho những giá trị mà chúng ta tin tưởng, là nền tảng để dựng nên cơ đồ. Người Việt coi mình cùng từ một bọc trứng, nên gọi nhau là đồng bào và con Lạc cháu Hồng. Những người anh hùng của Việt Nam đầy vinh quang, Trần Hưng Đạo, Nguyễn Trãi, Lê Lợi, và gần gũi với chúng ta là Hồ Chí Minh và Võ Nguyên Giáp. Lời Bà Triệu về quyền tự do còn vang mãi: Tôi muốn cưỡi cơn gió mạnh, đạp luồng sóng dữ, chém cá kình ở biển khơi, đánh đuổi quân Ngô giành lại giang sơn, cởi ách nô lệ, đâu chịu khom lưng làm tì thiếp cho người? Chị em Trưng Trắc, Trưng Nhị thà trẫm mình xuống sông thay vì đầu hàng giặc Hán; những anh hùng hi sinh trong lớp thanh niên Việt vì độc lập dân tộc đánh đuổi thực dân Pháp: Kim Đồng, Võ Thị Sáu, Phan Đình Giót, Bế Văn Đàn, Tô Vĩnh Diện, Nguyễn Thị Minh Khai, Nguyễn Thị Quang Thái, Lý Tự Trọng. Nguyễn Văn Trỗi trước những họng súng của đội xử bắn chính quyền Việt Nam Cộng hòa đưa ra lời nói sau cùng cũng còn ghi lại trong trí nhớ tập thể của người Việt: chính người Mỹ đã xâm lược đất nước ta, chính họ giết nhân dân ta bằng máy bay và bom đạn.. Tôi chưa bao giờ đi ngược lại ý chí nhân dân tôi. Tôi hành động để chống Mỹ.</i><br><i>Dân tộc Pháp cũng có những người anh hùng như vậy. Jeanne d’Arc, một thiếu nữ chăn cừu nghe thấy lời ba vị thánh cho biết Chúa đã chọn cô là người giải phóng đất nước đang bị người Anh xâm lược một phần. Giống như Bà Triệu, Bà Trưng, cô tập hợp quân đội đánh đuổi quân Anh khỏi bờ cõi Pháp. Cô bị người Burgundy, đồng minh của người Anh, bắt giữ và thiêu trên cọc khi mới mười chín tuổi.</i><br><i>Lịch sử được tạo nên từ những trang vinh quang và cả những trang tối tăm. Trí nhớ tập thể thường nhớ cái trước mà quên cái sau.</i><br><i>Tất cả những người anh hùng ấy đều cùng chia sẻ những giá trị bất diệt làm nên phẩm giá con người: trong sáng, chính trực, dũng cảm, nhân ái, tận hiến cho lẽ phải. Tất cả họ cũng đứng cùng về một phía: những người phục thù, chống lại điều sai trái, phục hồi công lý cho tổ quốc bị xâm lược tàn nhẫn và bất công bởi ngoại bang. Đối lập với họ là những kẻ thù xấu xa. Jeanne d’Arc bị tuyên án bởi Cauchon, vị linh mục đáng khinh theo đuổi không gì khác ngoài quyền lực, phản bội và bán rẻ tổ quốc cho người Anh. Nguyễn Văn Trỗi chết dưới tay các đao phủ của Nguyễn Khánh và Dương Văn Minh, những đầy tớ của người Mỹ. Kẻ thù của Kim Đồng, Võ Thị Sáu, Nguyễn Thị Minh Khai, Nguyễn Thị Quang Thái là thực dân Pháp ngạo mạn đáng xấu hổ, những cai ngục Côn Đảo cùng chuồng cọp của chúng.</i><br><i>Trí nhớ tập thể của một dân tộc, những huyền thoại và nghi lễ, cho chúng ta những người anh hùng để kính ngưỡng, những phẩm cách để tôn vinh, những tấm gương để học hỏi. Trí nhớ tập thể cũng chỉ ra những kẻ xấu đáng lên án: sự tàn ác, hèn hạ, hủ bại, ích kỷ, thối nát, phản trắc. </i><br>(Trí nhớ tập thể và danh tính dân tộc, Pierre Darriulat)", "cauHoi": [{"question": "Quan điểm chính của đoạn trích là gì?", "choices": ["Trí nhớ tập thể là nền tảng duy nhất giúp củng cố bản sắc và đoàn kết dân tộc.", "Việc học lịch sử cần vượt khỏi giới hạn của trí nhớ tập thể để hướng tới cái nhìn đầy đủ, khách quan và nhân văn hơn.", "Lịch sử của mỗi dân tộc được tạo nên chủ yếu từ các cuộc đấu tranh chống ngoại xâm và những người anh hùng tiêu biểu.", "Các biểu tượng và anh hùng dân tộc đóng vai trò quyết định trong việc hình thành ý thức quốc gia."], "correctIndex": 1, "explain": "<b>Câu 26: B.</b> Việc học lịch sử cần vượt khỏi giới hạn trí nhớ tập thể (Ngay đoạn đầu tác giả đã nêu vấn đề về việc học lịch sử không đầy đủ)."}, {"question": "Chi tiết nào sau đây là bằng chứng tiêu biểu nhất cho cách trí nhớ tập thể kiến tạo hình tượng anh hùng dân tộc?", "choices": ["Việc nêu các tiêu ngữ quốc gia như “Độc lập - tự do - hạnh phúc” hay “bình đẳng và bác ái”.", "Việc khẳng định lịch sử gồm cả những trang vinh quang và tối tăm.", "Việc dẫn lại lời nói của Bà Triệu và lời cuối của Nguyễn Văn Trỗi.", "Việc so sánh anh hùng của Việt Nam với anh hùng của Pháp."], "correctIndex": 2, "explain": "<b>Câu 27: C.</b> Việc dẫn lại lời nói của Bà Triệu và Nguyễn Văn Trỗi (Đây là cách trí nhớ tập thể lưu giữ &quot;phần hồn&quot; và khí phách của anh hùng)."}, {"question": "Nhận định nào sau đây không phù hợp với quan điểm của tác giả?", "choices": ["Trí nhớ tập thể góp phần nuôi dưỡng các giá trị và hình tượng mà một dân tộc tôn vinh.", "Học lịch sử giúp con người biết phân biệt lẽ phải và tham vọng bá quyền.", "Trí nhớ tập thể phản ánh đầy đủ và khách quan toàn bộ sự thật lịch sử.", "Những người anh hùng thường đại diện cho các phẩm giá như chính trực, dũng cảm và tận hiến."], "correctIndex": 2, "explain": "<b>Câu 28: C.</b> (Tác giả khẳng định &quot;thói thường khiến người ta học lịch sử một cách không đầy đủ&quot;, tức là trí nhớ tập thể thường phiến diện)."}, {"question": "Theo đoạn trích, việc tác giả nhắc đến Jeanne d’Arc nhằm mục đích chủ yếu nào?", "choices": ["Chứng minh rằng mọi dân tộc đều có những người anh hùng trẻ tuổi hi sinh vì đất nước.", "Làm rõ rằng lịch sử Pháp và Việt Nam có nhiều điểm tương đồng trong quá trình chống ngoại xâm.", "Cho thấy mỗi dân tộc đều có hệ thống biểu tượng và anh hùng được lưu giữ trong trí nhớ tập thể.", "Khẳng định rằng tôn giáo có vai trò quyết định trong việc hình thành các anh hùng dân tộc."], "correctIndex": 2, "explain": "<b>Câu 29: C.</b> Cho thấy mỗi dân tộc đều có hệ thống biểu tượng và anh hùng (Dùng phương pháp so sánh tương đồng)."}, {"question": "<i>Trí nhớ tập thể của một dân tộc, những huyền thoại và nghi lễ, cho chúng ta những người anh hùng để kính ngưỡng, những phẩm cách để tôn vinh, những tấm gương để học hỏi.</i><br>Đây là câu ____", "choices": ["Câu ghép chính phụ", "Câu ghép đẳng lập", "Câu đơn", "Câu ghép hô ứng"], "correctIndex": 2, "explain": "<b>Câu 30: C.</b> <b>Câu đơn</b> (Câu có nhiều vị ngữ song song nhưng chỉ có một cụm Chủ - Vị chính)."}], "khongXaoTron": true}], "anh": [{"noiDungChung": "<b><i>Câu 31-35: Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following Câus.</i></b>", "cauHoi": [{"question": "To enter the restricted area, you __________ carry a valid identification badge.", "choices": ["should", "will", "might", "must"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 31. Chọn D (must)</b><br>Giải thích: Diễn tả sự <b>bắt buộc/điều kiện bắt buộc</b> để vào khu vực hạn chế → dùng <i>must</i>."}, {"question": "Young children are often ______________ and can be shaped by their<br>surroundings.", "choices": ["impressive", "impressed", "impressing", "impressionable"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 32. Chọn D (impressionable)</b><br>Giải thích: <i>Impressionable</i> = dễ bị ảnh hưởng → phù hợp với “có thể bị môi trường tác động”."}, {"question": "The movie was so __________ that she couldn’t stop thinking about it for days.", "choices": ["moved", "moving", "move", "movable."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 33. Chọn B (moving)</b><br>Giải thích: <i>Moving</i> (gây xúc động) dùng cho vật/sự việc; <i>moved</i> dùng cho người."}, {"question": "The report needs __________ before the meeting next week to ensure all data<br>is accurate.", "choices": ["to finalize", "finalizing", "finalize", "to finalizing"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 34. Chọn B (finalizing)</b><br>Giải thích: <i>Need + V-ing</i> (bị động nghĩa) = cần được hoàn thiện → “needs finalizing”"}, {"question": "After years of hard work and dedication, she finally decided to __________<br>her dream of opening a bakery.", "choices": ["set her heart on", "put her foot down on", "keep her options open", "be a leap of faith"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 35. Chọn A (set her heart on)</b><br>Giải thích: Nghĩa là “quyết tâm làm gì đó” → phù hợp ngữ cảnh."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 36-40: Each of the following sentences has one error (A, B, C, or D). Find it and blacken your choice on your answer sheet.</i></b>", "cauHoi": [{"question": "According to the schedule, <u>the</u> <u>group</u> of students <u>are</u> visiting the museum <u>at</u> 9 AM tomorrow.", "choices": ["the", "group", "are", "at"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 36. Chọn C (are → is)</b><br>Giải thích: Chủ ngữ “the group” là số ít → dùng <i>is</i>."}, {"question": "The <u>pollution</u> in the city <u>has become</u> <u>serious</u> lately, <u>isn&#x27;t it</u>?", "choices": ["pollution", "has become", "serious", "isn&#x27;t it"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 37. Chọn D (isn&#x27;t it → hasn&#x27;t it)</b><br>Giải thích: Mệnh đề chính dùng hiện tại hoàn thành → tag question phải là <i>hasn&#x27;t it</i>"}, {"question": "If I <u>know</u> her <u>phone number</u>, I <u>would call</u> her <u>right now</u>.", "choices": ["know", "phone number", "would call", "right now."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 38. Chọn A (know → knew)</b><br>Giải thích: Câu điều kiện loại 2 → <i>If + S + V2</i>."}, {"question": "He <u>was</u> <u>so</u> a <u>talented</u> singer that everyone <u>admired</u> him.", "choices": ["was", "so", "talented", "admired."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 39. Chọn B (so → such)</b><br>Giải thích: Cấu trúc đúng: <i>such a + adj + noun</i>."}, {"question": "The <u>results</u> of the <u>study</u> <u>was</u> published in a <u>prestigious</u> journal last month.&quot;", "choices": ["results", "study", "was", "prestigious"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 40. Chọn C (was → were)</b><br>Giải thích: Chủ ngữ “results” số nhiều → dùng <i>were</i>."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "Exercising outdoors could improve your mood more effectively than staying", "choices": ["Staying indoors all day may be more effective for improving your mood than exercising", "Exercising outdoors is certainly more effective for improving your mood than staying indoors.", "Exercising outdoors may improve your mood more effectively than staying indoors all day.", "It’s possible that staying indoors all day is as effective for improving your mood as exercising ourdoors."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 41. Chọn C Giải thích: Câu gốc dùng &quot;could&quot; (có thể). Câu C giữ nguyên nghĩa &quot;may improve&quot; (có thể cải thiện) và cấu trúc so sánh.</b>"}, {"question": "The coffee was so hot that I had to wait a few minutes before drinking it.", "choices": ["The coffee was too hot for me to drink immediately.", "The coffee was hot enough that I needed to wait a few minutes before drinking it.", "The coffee was such a high temperature that I couldn’t drink it right away.", "The coffee was so hot that I couldn’t wait to drink it immediately."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 42. Chọn A</b> <b>Giải thích:</b> Cấu trúc &quot;So... that&quot; (Quá... đến nỗi mà) tương đương với &quot;Too... for somebody to V&quot; (Quá... để cho ai làm gì)."}, {"question": "Her talent for painting earned her recognition from art critics and enthusiasts<br>alike.", "choices": ["Art critics and enthusiasts praised her paintings because of her talent.", "Her talent for painting led to her recognition by art critics and enthusiasts.", "Recognition from art critics and enthusiasts was earned through her remarkable paintings.", "She was recognized by art critics and enthusiasts for her paintings."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 43. Chọn B</b> <b>Giải thích:</b> Câu gốc nói về tài năng mang lại sự công nhận. Câu B diễn đạt chính xác: &quot;Tài năng dẫn đến việc cô ấy được công nhận&quot;."}, {"question": "She had never been so excited to visit her grandparents&#x27; house as she was last weekend.", "choices": ["Never before had she been as excited to visit her grandparents&#x27; house as last weekend.", "Rarely had she been as excited as she was to visit her grandparents&#x27; house last weekend.", "Not only had she been excited to visit her grandparents&#x27; house last weekend, but also she<br>couldn’t wait for the next trip.", "Hardly had she been so excited to visit her grandparents’ house than last weekend."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 44. Chọn A</b> <b>Giải thích:</b> Cấu trúc đảo ngữ với &quot;Never&quot;: <b>Never before + had + S + V3/ed... as + adj + as...</b> (Chưa bao giờ cô ấy hào hứng như cuối tuần trước)."}, {"question": "The company has announced plans to launch a new product. It’s uncertain whether the product will succeed in the market.", "choices": ["The company’s new product will definitely succeed in the market.", "The product launch could potentially be successful.", "It’s almost certain that the new product will fail in the market.", "The company’s new product is unlikely to succeed in the market."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 45. Chọn B</b> <b>Giải thích:</b> Câu gốc nói về sự không chắc chắn (uncertain). &quot;Could potentially be&quot; (có tiềm năng/có khả năng) phản ánh đúng tính chất không chắc chắn này."}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question. Choose an option (A, B, C, or D) that best answers each question.</i></b><br>The pursuit of happiness is central to the human experience. However, a modern cultural trend known as &quot;toxic positivity&quot; presents a significant challenge to authentic well-being. This is the pervasive belief that one must maintain a positive mindset, regardless of the circumstances. As this mindset is projected to constitute a major societal pressure, innovative methods for genuine emotional processing are imperative.<br>One of the primary harms of toxic positivity is emotional invalidation. When individuals express legitimate sadness, fear, or anxiety, <b>they</b> are often met with dismissive platitudes like &quot;just be positive&quot; or &quot;look on the bright side.&quot; This response, though often well-intentioned, communicates that their negative feelings are &#x27;wrong&#x27; or &#x27;unacceptable&#x27;.<br>Furthermore, toxic positivity fosters a culture of shame and suppression. It implies that feeling anything other than happiness is a sign of personal failure. This cognitive dissonance—the profound gap between what one truly feels and what one is &quot;supposed&quot; to feel—can significantly exacerbate underlying mental health issues. It amplifies internal pressure, forcing individuals to wear a &#x27;mask&#x27; of happiness, which is profoundly isolating.<br>This phenomenon also prevents genuine human connection. True empathy involves validating someone&#x27;s struggle, not dismissing it with superficial optimism. By offering empty slogans, we communicate that we are uncomfortable with their pain. This superficial interaction erodes the foundation of trust and vulnerability, making authentic relationships impossible to sustain.<br>Equity in emotional expression is fundamental, ensuring that the space to feel is distributed fairly. This involves providing access to affordable mental healthcare that caters to diverse income levels.<br>Moreover, toxic positivity can lead to poor decision-making. Techniques such as ignoring &quot;red flags&quot; in a relationship or a job, under the guise of &quot;staying positive,&quot; address symptoms rather than root causes. Collaboration between individuals and therapists is vital to implementing realistic solutions.<br>By adopting authentic emotional practices, individuals can enhance resilience. Harmonizing the need for optimism with the acceptance of difficult emotions ensures a sustainable future for holistic mental health.", "cauHoi": [{"question": "What does &quot;<b>they</b>&quot; in paragraph 2 refer to?", "choices": ["dismissive platitudes", "emotional invalidation", "negative feelings", "individuals expressing legitimate sadness, fear, or anxiety"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 46. Chọn D</b> <b>Giải thích:</b> Trong đoạn 2, &quot;they&quot; thay thế cho danh từ số nhiều đứng trước nó: &quot;individuals expressing legitimate sadness, fear, or anxiety&quot;."}, {"question": "According to paragraph 3, what is one of the harms of toxic positivity?", "choices": ["It is a sign of personal success and resilience.", "It forces individuals to wear a &#x27;mask&#x27; of happiness.", "It bridges the gap between what one truly feels and what one is supposed to feel.", "It is an effective way to manage cognitive dissonance."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 47. Chọn B</b> <b>Giải thích:</b> Đoạn 3 có câu: &quot;...forcing individuals to wear a &#x27;mask&#x27; of happiness&quot; (buộc cá nhân phải đeo một chiếc mặt nạ hạnh phúc)."}, {"question": "What is the main topic of paragraph 4?", "choices": ["The importance of vulnerability in leadership.", "How toxic positivity erodes trust and authentic connection.", "A list of empty slogans and their origins.", "Why &#x27;Look on the bright side!&#x27; is a useful phrase."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 48. Chọn B</b> <b>Giải thích:</b> Đoạn 4 tập trung vào việc toxic positivity ngăn cản sự kết nối thực sự và làm xói mòn niềm tin (&quot;erodes the foundation of trust&quot;)."}, {"question": "Based on the passage, which of the following is NOT a consequence of toxic positivity?", "choices": ["It damages authentic relationships.", "It leads to poor decision-making by ignoring root causes.", "It is the most effective way to process pain and build resilience.", "It makes people feel isolated and ashamed of their negative feelings."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 49. Chọn C</b> <b>Giải thích:</b> Đoạn cuối nhấn mạnh việc chấp nhận cả cảm xúc khó khăn mới là bền vững. Khẳng định toxic positivity là &quot;cách hiệu quả nhất&quot; (the most effective way) là sai"}, {"question": "Which of the following would the author most likely support?", "choices": ["True mental health involves accepting both positive and negative emotions.", "The only way to be resilient is to ignore pain and focus on the positive.", "People who feel sad or anxious are demonstrating a personal failure.", "&quot;Tragic optimism&quot; is just another form of toxic positivity."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 50. Chọn A</b> <b>Giải thích:</b> Tác giả ủng hộ &quot;authentic emotional practices&quot; (thực hành cảm xúc chân thực) và &quot;acceptance of difficult emotions&quot; (chấp nhận cảm xúc khó khăn)."}, {"question": "Which of the following best summarizes the author&#x27;s argument regarding the impact of toxic positivity on interpersonal relationships?", "choices": ["It strengthens bonds by encouraging partners to focus only on joyful experiences.", "It creates a facade of happiness that facilitates easier social interactions.", "It undermines the essence of empathy by replacing validation with superficial optimism.", "It promotes equity by ensuring everyone maintains a standard level of positivity."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 51. Chọn C</b> <b>Giải thích:</b> Tác giả lập luận rằng sự lạc quan hời hợt (superficial optimism) làm mất đi bản chất của sự thấu cảm (empathy)."}, {"question": "In the third paragraph, the phrase &quot;<b>wear a mask</b> <b>of</b> <b>happiness</b>&quot; is closest in meaning to:", "choices": ["Adopting a cheerful disposition to inspire others during difficult times.", "Concealing genuine distress to comply with perceived societal expectations.", "Utilizing positive affirmations to overcome internal cognitive dissonance.", "Protecting one&#x27;s privacy by refusing to share personal failures with strangers."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 52. Chọn B</b> <b>Giải thích:</b> &quot;Wear a mask of happiness&quot; có nghĩa là che giấu nỗi đau thật sự để tỏ ra vui vẻ theo mong đợi của xã hội."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1. </b>Social mobility, often called the &quot;kidneys of the state,&quot; is among the most valuable assets of a<br>healthy society. This abstract concept provides essential services: it ensures fairness, maintains<br>public trust, stores human potential, and serves as a habitat for aspiration. Despite being a core tenet of modern democracies, its immense value is often underappreciated, resulting in widespread stagnation and class rigidity. As noted by researchers, true intergenerational mobility (a child<br>earning more than their parents) has significantly declined since 1970.<br><b>2.</b> One of the primary reasons mobility is indispensable is its unparalleled ability to sustain a meritocracy. These systems act as vital habitats for talent, ranging from ambitious entrepreneurs and scientists to artists and skilled laborers. Narratives of &quot;upward mobility&quot; serve as fuel for the workforce, motivating individuals to pursue education and innovation. For instance, high- achieving students from low-income backgrounds heavily depend on this promise as a pathway out of poverty, demonstrating the critical role mobility plays in global talent allocation.<br><b>3.</b> In addition to being a talent pipeline, mobility contributes significantly to social stability. <b>They</b><br>function as psychological &quot;release valves,&quot; trapping public discontent and enhancing social cohesion. Mobility also regulates economic cycles by allowing talent to flow to where it is needed, thereby reducing inequality. Furthermore, this dynamic is highly effective at fostering innovation. Research indicates that societies with high mobility can sequester &quot;human capital&quot; at rates 10 times<br>higher than rigid, class-based societies. This ability to unlock human potential makes mobility a<br>crucial ally in mitigating the effects of economic shocks.<br><b>4.</b> Despite their economic and social importance, mobility pathways face severe threats. Over the past century, class structures have hardened due to human activities such as &quot;opportunity hoarding&quot; (where the wealthy secure advantages for their children), unequal educational funding, and nepotism. Draining the &quot;public good&quot; of education for private advantage disrupts the delicate social<br>fabric, leading to a cascade of lost potential and the disappearance of essential &quot;bridging capital.&quot;<br><b>5.</b> To address these alarming trends, global policy efforts are gaining momentum. Initiatives such<br>as reforming tax codes focus on identifying and reducing inherited wealth advantages. Restoration<br>projects aim to rehabilitate equal opportunity by reforming educational funding and mitigating opportunity hoarding. Moreover, public awareness campaigns highlight the dangers of inequality. As The Guardian emphasizes, the collaborative involvement of governments, private sectors, and local communities is pivotal in safeguarding this vital societal function.<br><b>6. </b>In conclusion, social mobility is indispensable to global economic health. It provides critical pathways for talent, stabilizes societies, and mitigates inequality. However, the continued <b>ossification</b> of class structures poses a severe threat to these functions. Protecting mobility is not only an economic imperative but a moral responsibility to ensure a sustainable future.", "cauHoi": [{"question": "Which of the following can be inferred from paragraph 1 regarding the current state of social mobility?", "choices": ["Modern democracies have successfully eliminated class rigidity through intergenerational mobility.", "The decline in children out-earning their parents indicates a weakening of a core democratic tenet.", "The &quot;kidneys of the state&quot; metaphor suggests that social mobility is a non-essential luxury for healthy societies.", "Researchers have only recently begun to value social mobility as a tool for public trust since 1970.s"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 53. Chọn B</b> <b>Giải thích:</b> Đoạn 1 nêu rõ tính di động xã hội là &quot;core tenet&quot; (nguyên tắc cốt lõi) và nó đang &quot;significantly declined&quot; (sụt giảm đáng kể)."}, {"question": "What is &quot;<b>ossification</b>&quot; in paragraph 6 closest in meaning to?", "choices": ["flexibility", "stagnation", "transparency", "growth"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 54. Chọn B</b> <b>Giải thích:</b> <b>Ossification</b> (sự hóa xương/trở nên cứng nhắc) đồng nghĩa với <b>stagnation</b> (sự trì trệ, không thay đổi)."}, {"question": "What does &quot;<b>They</b>&quot; in paragraph 3 refer to?", "choices": ["Social stability", "Human capital", "Narratives of &quot;upward mobility&quot;", "Psychological &quot;release valves&quot;"], "correctIndex": 3, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 55. Chọn D</b> <b>Giải thích:</b> Ở đoạn 3, &quot;They&quot; thay thế cho &quot;psychological release valves&quot; (những van xả tâm lý) ngay phía trước."}, {"question": "According to paragraph 3, social mobility acts as a &quot;psychological release valve&quot; because:", "choices": ["It sequesters human capital to prevent it from affecting economic cycles.", "It allows talent to flow toward private advantages, reducing the burden on the state.", "It minimizes public dissatisfaction by providing a realistic hope for upward progress.", "It helps individuals release their stress through artistic and scientific innovation."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 56. Chọn C</b> <b>Giải thích:</b> Van xả tâm lý giúp &quot;trapping public discontent&quot; (giữ lại sự bất mãn công chúng), tức là giảm thiểu sự không hài lòng bằng cách trao hy vọng."}, {"question": "The author uses the term &quot;opportunity hoarding&quot; in paragraph 4 to describe a process that:", "choices": ["Increases educational funding for low-income students through tax reforms.", "Enhances &quot;bridging capital&quot; by connecting diverse social classes.", "Solidifies class structures by restricting access to advantages to a privileged few.", "Encourages the private sector to collaborate with local communities for the public good."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 57. Chọn C</b> <b>Giải thích:</b> &quot;Opportunity hoarding&quot; được giải thích là nơi người giàu giữ chặt lợi thế cho con cái họ, làm cứng nhắc cấu trúc tầng lớp."}, {"question": "Which of the following best paraphrases this sentence:<br><b>&quot;Restoration projects aim to rehabilitate equal opportunity by reforming educational funding and mitigating opportunity hoarding.&quot;</b>", "choices": ["Initiatives are focused on fixing equal opportunity by changing how schools are funded and reducing the unfair reservation of advantages.", "The goal of restoration is to revitalize damaged opportunities by replacing native funding and altering hoarding conditions.", "Rehabilitation projects seek to restore opportunities by removing invasive funding and controlling native vegetation.", "Restoration projects focus on reintroducing native opportunities and managing water flow to improve the health of damaged systems. Hướng dẫn: Câu 58. Chọn A Giải thích: Bản dịch sát nghĩa: Phục hồi cơ hội bình đẳng bằng cách cải cách quỹ giáo dục và giảm bớt việc tích trữ cơ hội bất công."], "correctIndex": 0, "explain": ""}, {"question": "What is paragraph 4 mainly about?", "choices": ["The significant contributions of mobility to the economy.", "The structural barriers and human activities that obstruct social mobility.", "The process of draining education for private advantage.", "The impact of nepotism and &quot;opportunity hoarding&quot; on taxation."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 59. Chọn B</b> <b>Giải thích:</b> Đoạn 4 nói về các mối đe dọa (threats) và các rào cản (nepotism, unequal funding) ngăn cản di động xã hội."}, {"question": "Which of the following does the author probably support?", "choices": ["Prioritizing the preservation of existing class structures to maintain societal stability.", "Encouraging widespread public and governmental intervention to fix the &quot;broken rungs&quot; of the social ladder.", "Focusing exclusively on individual hard work (meritocracy) as the only solution to inequality.", "Allowing &quot;opportunity hoarding&quot; to balance economic and social needs."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Câu 60. Chọn B</b> <b>Giải thích:</b> Tác giả ủng hộ các nỗ lực chính sách toàn cầu, sự tham gia của chính phủ và cộng đồng để bảo vệ chức năng quan trọng này."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Các chất có khuynh hướng tách khỏi bề mặt của chất lỏng để chuyển thành trạng thái hơi và gây áp suất hơi. Khi tốc độ bay hơi bằng tốc độ ngưng tụ thì áp suất hơi lúc đó gọi là áp suất hơi bão hòa. Áp suất hơi bão hòa tỷ lệ thuận với nhiệt độ. Ở nhiệt độ mà áp suất hơi bão hòa bằng áp suất khí quyển thì nhiệt độ đó chính là nhiệt độ sôi của chất lỏng. Biết áp suất hơi bão hòa của hỗn hợp hơi bằng tổng áp suất hơi bão hòa riêng phần của các chất trong hỗn hợp.<br><table class=\"bang-de\"><tr><td>Hỗn hợp</td><td>n-heptane (mol)</td><td>n-octane (mol)</td><td>Áp suất hơi bão hòa của hỗn hợp ở \\(\\mathbf{25}^{\\mathbf{\\circ}}\\mathbf{C}\\) (mmHg)</td></tr><tr><td>1</td><td>0,0</td><td>1,0</td><td>14,0</td></tr><tr><td>2</td><td>0,2</td><td>0,8</td><td>20,4</td></tr><tr><td>3</td><td>0,4</td><td>0,6</td><td>26,8</td></tr><tr><td>4</td><td>0,5</td><td>0,5</td><td>30,0</td></tr><tr><td>5</td><td>0,6</td><td>0,4</td><td>33,2</td></tr><tr><td>6</td><td>0,8</td><td>0,2</td><td>39,6</td></tr><tr><td>7</td><td>1,0</td><td>0,0</td><td>46,0</td></tr></table>", "cauHoi": [{"question": "Một hỗn hợp có số mol n-heptane lớn hơn 0,4 nhưng nhỏ hơn 0,5. Áp suất hơi bão hòa của hỗn hợp này có thể nhận giá trị nào sau đây?", "choices": ["26,8 mmHg", "28,5 mmHg", "30,0 mmHg", "33,2 mmHg"], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> <b>Đáp án: B, vì </b>số mol n-heptane lớn hơn 0,4 nhưng nhỏ hơn 0,5 \\(\\Rightarrow\\) Áp suất hơi bão hòa của hỗn hợp này không bằng 26,8 và 30 mmHg, mà nằm giữa khoảng này \\(\\Rightarrow\\) đáp án: B<br><table class=\"bang-de\"><tr><td>3</td><td>0,4</td><td>0,6</td><td><b>26,8</b></td></tr><tr><td>4</td><td>0,5</td><td>0,5</td><td><b>30,0</b></td></tr></table>"}, {"question": "Xét hỗn hợp hai chất lỏng n-heptane (H) và n-octane (O) ở cùng nhiệt độ. Trong các nhận định sau, nhận định nào <b>có thể suy ra không chính xác</b> từ các dữ kiện về áp suất hơi bão hòa của hỗn hợp?", "choices": ["Khi tăng phần mol n-heptane thì áp suất hơi của hỗn hợp tăng.", "Áp suất hơi của hỗn hợp luôn nằm giữa áp suất hơi của hai chất tinh khiết.", "Áp suất hơi của hỗn hợp không thay đổi khi thay đổi tỉ lệ hai chất.", "Trong hỗn hợp, mỗi chất đều bay hơi kém hơn so với khi ở trạng thái tinh khiết."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Đáp án: C</b>"}, {"question": "Xét hỗn hợp hai chất lỏng n-heptane (H) và n-octane (O). Biết rằng khi xét cùng nhiệt độ thì n-heptane có áp suất hơi bão hòa lớn hơn n-octane.<br>Xét hai hệ:<br>Hệ X: hỗn hợp H–O ở áp suất khí quyển 760 mmHg, nhiệt độ sôi là T<sub>X</sub><br>Hệ Y: cùng hỗn hợp trên nhưng ở áp suất khí quyển 600 mmHg, nhiệt độ sôi là T<sub>Y</sub><br>Nhận định nào sau đây đúng?", "choices": ["T<sub>X</sub> = T<sub>Y</sub> vì nhiệt độ sôi không phụ thuộc áp suất khí quyển.", "T<sub>X</sub> &lt; T<sub>Y</sub> vì áp suất khí quyển lớn hơn làm chất lỏng dễ bay hơi hơn.", "T<sub>X</sub> &gt; T<sub>Y </sub> vì khi áp suất khí quyển giảm, chất lỏng sôi ở nhiệt độ thấp hơn.", "T<sub>X</sub> &lt; T<sub>Y</sub> vì n-octane chiếm ưu thế trong hỗn hợp nên làm giảm nhiệt độ sôi khi áp suất thay đổi."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> <b>Đáp án: C, </b>vì ở nhiệt độ mà áp suất hơi bão hòa bằng áp suất khí quyển thì nhiệt độ đó là nhiệt độ sôi. Nếu áp suất khí quyển giảm (760 → 600 mmHg), áp suất hơi bão hòa chỉ cần đạt đến giá trị thấp hơn đó là đã sôi rồi, nên nhiệt độ sôi phải <b>giảm.</b><br>\\(\\Rightarrow\\) chất lỏng dễ sôi hơn<br>\\(\\Rightarrow\\) nhiệt độ sôi giảm \\(\\Rightarrow\\) T<sub>X</sub> &gt; T<sub>Y </sub>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br><img class=\"anh-de\" src=\"data/anh/l12/3b9414fe4f04ac1f.png\" alt=\"\" style=\"width:139px;height:190px\">Kỹ thuật mạ điện hay kĩ thuật Galvano (lấy tên theo nhà khoa học Ý Luigi Galvani) là tên gọi của quá trình điện hóa phủ lớp kim loại lên một vật. Phương pháp mạ điện bạc trong dung dịch <img class=\"anh-de\" src=\"data/anh/l12/b07b0ea6cbf1cfac.png\" alt=\"\" style=\"width:50px;height:24px;vertical-align:middle\"> sử dụng dòng điện để tạo lớp phủ bạc trên bề mặt vật cần mạ. Điện cực âm (catod) là vật cần mạ, nơi ion bạc <img class=\"anh-de\" src=\"data/anh/l12/3a59b706d03b0341.png\" alt=\"\" style=\"width:30px;height:24px;vertical-align:middle\">di chuyển đến và bám vào bề mặt. Điện cực dương (anod) là tấm bạc nguyên chất, cung cấp thêm ion bạc <img class=\"anh-de\" src=\"data/anh/l12/627ce18c26fb5b8a.png\" alt=\"\" style=\"width:30px;height:24px;vertical-align:middle\">vào dung dịch trong quá trình mạ. Lớp bạc được mạ giúp tăng tính dẫn điện và chống mài mòn<br>Khối lượng bạc (Ag) được mạ lên được tính bằng công thức<br>Trong đó:<img class=\"anh-de\" src=\"data/anh/l12/2a887f5e75188ffa.png\" alt=\"\" style=\"width:17px;height:15px;vertical-align:middle\"> : (đ̛ơn vi g).<br><img class=\"anh-de\" src=\"data/anh/l12/43cebda7fbcddf18.png\" alt=\"\" style=\"width:21px;height:17px;vertical-align:middle\"> : Khối lượng mol của bạc (Ag) (khoảng 107,87 g/mol).<br>I: Cường độ dòng điện qua dung dịch (đơn vị: A).<br><img class=\"anh-de\" src=\"data/anh/l12/0a9425e7e3fbb437.png\" alt=\"\" style=\"width:10px;height:16px;vertical-align:middle\"> : Thời gian mạ điện (đơn vị s).<br><img class=\"anh-de\" src=\"data/anh/l12/10fd4c6b0b89d618.png\" alt=\"\" style=\"width:13px;height:15px;vertical-align:middle\"> : Số electron cần thiết để khử ion bạc thành bạc nguyên chất (đối với bạc, <img class=\"anh-de\" src=\"data/anh/l12/7e7c4cf71ed14f9c.png\" alt=\"\" style=\"width:35px;height:18px;vertical-align:middle\"> vì ion bạc <img class=\"anh-de\" src=\"data/anh/l12/cf26892af0bb934e.png\" alt=\"\" style=\"width:30px;height:24px;vertical-align:middle\">nhận 1 electron để trở thành Ag)<br>F: Hằng số Faraday ( <img class=\"anh-de\" src=\"data/anh/l12/7d1485f82339141e.png\" alt=\"\" style=\"width:97px;height:21px;vertical-align:middle\">, đại diện cho điện tích của 1 mol electron.", "cauHoi": [{"question": "Phát biểu nào sau đây là <b>sai</b> khi nói về cách mạ bạc một huy chương?", "choices": ["Chất điện phân là dung dịch muối \\({AgNO}_{3}\\).", "Dùng Anot bằng bạc.", "Đặt huy chương trong khoảng giữa anot và catod.", "Dùng huy chương làm Catod."], "correctIndex": 2, "explain": "<b><u>Hướng dẫn:</u></b> Bài đọc nói “Điện cực âm (catod) là vật cần mạ, nơi ion bạc <img class=\"anh-de\" src=\"data/anh/l12/3a59b706d03b0341.png\" alt=\"\" style=\"width:30px;height:24px;vertical-align:middle\">di chuyển đến và bám vào bề mặt”, nghĩa là muốn mạ bạc cho huy chương thì cần phải đặt huy chương tại cực catod, câu D đúng<br><b>Chọn câu C là câu sai!!!</b><br><b>Câu 107. </b> Để mạ đồng cho một huy chương, các điện cực và dung dịch điện phân cần lựa chọn như thế nào?"}, {"question": "", "choices": ["Huy chương làm điện cực dương, tấm đồng làm điện cực âm, dung dịch <img class=\"anh-de\" src=\"data/anh/l12/55a71b58e8ab6b93.png\" alt=\"\" style=\"width:47px;height:24px;vertical-align:middle\">.", "Huy chương làm điện cực âm, tấm đồng làm điện cực dương, dung dịch <img class=\"anh-de\" src=\"data/anh/l12/55a71b58e8ab6b93.png\" alt=\"\" style=\"width:47px;height:24px;vertical-align:middle\">.", "Huy chương làm điện cực âm, tấm sắt làm điện cực dương, dung dịch <img class=\"anh-de\" src=\"data/anh/l12/c1344ca6e1e6ce6b.png\" alt=\"\" style=\"width:47px;height:24px;vertical-align:middle\">.", "Huy chương làm điện cực âm, tấm đồng làm điện cực dương, dung dịch <img class=\"anh-de\" src=\"data/anh/l12/8a2344898b338d99.png\" alt=\"\" style=\"width:47px;height:24px;vertical-align:middle\">."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn: </u></b>Chọn câu B. Để <b>mạ đồng (Cu)</b> cho huy chương:<br><b>Huy chương phải làm catot (cực âm)</b> → nơi ion Cu²⁺ nhận electron và bám lên bề mặt.<br><b>Anot phải là tấm đồng (Cu)</b> → để Cu tan ra bổ sung Cu²⁺ vào dung dịch.<br><b>Dung dịch điện phân</b>: phải chứa ion Cu²⁺ (thường là <b>CuSO₄</b>)."}, {"question": "Người ta muốn bọc một lớp đồng dày \\(d = 10\\mu m\\) trên một bản đồng điện tích \\(S = 1{\\text{ }cm}^{2}\\) bằng phương pháp điện phân. Cuờng độ dòng điện là \\(0,010\\text{ }A\\). Cho biết đồng có khối lượng riêng là \\(\\rho = 8900\\text{ }kg/m^{3},\\text{ }A = 64;n = 2\\). Thời gian cần thiết để bọc được lớp đồng như trên là:", "choices": ["Khoảng 1h", "Khoảng 3/4 giờ", "Khoảng 1/2 giờ", "Khoảng 1/4 giờ"], "correctIndex": 0, "explain": "<b><u>Hướng dẫn: </u></b>- Khối lượng đồng cần bọc cho bản đồng là:<br>\\[m = V.\\rho = S.d.\\rho = 10^{- 4} \\cdot 10 \\cdot 10^{- 6} \\cdot 8900 \\cdot 10^{3} = 8,9 \\cdot 10^{- 3}\\text{ }g\\]<br>- Mặt khác, theo định luật Faraday khối lượng đồng cần bọc cho bản đồng trong thời gian t là:<br>\\(m = \\frac{1}{\\text{ }F} \\cdot \\frac{A}{n}\\).I.t<br>- Thời gian cần thiết để bọc được lớp đồng là:<br>\\(t = \\frac{m \\cdot F \\cdot n}{\\text{~A.I~}} = \\frac{8,9 \\cdot 10^{- 3} \\cdot 96500 \\cdot 2}{64 \\cdot 0,010} = 2684\\text{ }s = 44,73\\text{~phút~}\\)Chọn câu A"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Quang hợp là quá trình thực vật, tảo và vi khuẩn lam chuyển đổi năng lượng ánh sáng Mặt Trời thành năng lượng tích lũy trong các liên kết hóa học. Diệp lục là sắc tố được các sinh vật tự dưỡng sử dụng để hấp thụ các bước sóng khác nhau của ánh sáng khả kiến từ Mặt Trời để sử dụng cho quá trình quang hợp. Có nhiều loại sắc tố quang hợp, chúng có các cấu tạo đặc biệt để hấp thụ được nhiều phạm vi khác nhau của quang phổ ánh sáng khả kiến và phản xạ các phạm vi còn lại. Phổ hấp thụ của chất diệp lục và các sắc tố phụ có thể thu được thông qua phép đo quang phổ và được sử dụng trong các phân tích về sự phát triển của thực vật, nhằm xác định sự phong phú của các sinh vật quang hợp trong nước ngọt hoặc nước mặn và đánh giá chất lượng nước. Số liệu trong hình và bảng dưới đây được thu thập bởi các nhóm sinh viên khi đo phố hấp thụ của ba sắc tố quang hợp thường gặp", "cauHoi": [{"question": "Dựa vào Hình 1, cho biết bước sóng của ánh sáng khả kiến nào sau đây sẽ được hấp thụ để thúc đẩy hoạt động quang hợp mạnh nhất ở cây xanh?", "choices": ["400 nm .", "450 nm .", "550 nm .", "525 nm ."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn:</u></b> Dựa vào đồ thị, ta thấy bước sóng được hấp thu cao nhất nằm ở vùng 450 nm"}, {"question": "Dựa vào thông tin được cung cấp trong Hình 1 và Bảng 1, cho biết phát biểu nào sau đây là đúng?", "choices": ["Cả chlorophyll \\(a\\), chlorophyll \\(b\\) và carotenoid đều không hấp thụ ánh sáng có bước sóng từ 425 đến 475 nm .", "Chlorophyll a và chlorophyll b hấp thụ ánh sáng xanh lục (~500–570 nm) hấp thụ ít nhất", "Chlorophyll a và chlorophyll b có độ phản xạ mạnh nhất ở bước sóng từ 525 đến 625 nm.", "Carotenoid hấp thụ nhiều ánh sáng nhất ở vùng ánh sáng đỏ của quang phổ."], "correctIndex": 1, "explain": "HD: Chúng ta thấy lá cây có màu xanh vì Chlorophyll a và chlorophyll b hấp thụ ánh sáng xanh lục (~500–570 nm) hấp thụ ít nhất, nghĩa là phản xạ màu xanh lục nhiều nhất đến mắt ta"}, {"question": "Phát biểu nào sau đây là đúng?", "choices": ["Thực vật quang hợp mạnh nhất ở miền ánh sáng lục.", "Ánh sáng có hiệu quả lớn nhất tới quang hợp là ánh sáng vàng.", "Quang hợp xảy ra ở miền ánh sáng đỏ và miền ánh sáng xanh tím.", "Carotenoid (carotenoid) là một nhóm sắc tố phụ trong quang hợp có trong thực vật, tảo và một số vi khuẩn có màu xanh lục"], "correctIndex": 2, "explain": "HD: Dựa vào phổ hấp thu của các chất diệp lục, ta thấy đỉnh hấp thu nằm trong vùng màu xanh tím (mạnh nhất) và vùng màu đỏ (mạnh) <b>Chọn C</b><br>Nhìn vào đồ thị, Carotenoid hấp thụ mạnh ở vùng ~400–500 nm→ tức là ánh sáng lam – tím đã bị hấp thu mạnh<br>Còn vùng: Vàng (570–590 nm) ; Cam (590–620 nm); Đỏ (620–750 nm) → hấp thụ rất yếu<br>Ánh sáng phản xạ là vàng – cam – đỏ là màu chủ đạo của Carotenoid → D sai!<br><img class=\"anh-de\" src=\"data/anh/l12/6a08b462c1ad2d26.png\" alt=\"\" style=\"width:371px;height:237px\">"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>&quot;Những năm gần đây, các địa phương vùng Đồng bằng sông Cửu Long phải đối mặt với nhiều thách thức do ảnh hưởng của biến đổi khí hậu, nước biển dâng, quá trình phát triển ở thượng nguồn sông Mê Công. gây tình trạng hạn hán, xâm nhập mặn, ô nhiễm nguồn nước, sạt lở, lún sụt. Riêng mùa khô năm 2023-2024, ở khu vực này hạn hán, xâm nhập mặn đã ảnh hưởng đến hàng nghìn héc-ta cây trồng và hàng chục nghìn hộ dân thiếu nước sinh hoạt. Xâm nhập mặn sẽ tác động đến 10/13 tỉnh của ĐBSCL, bao gồm: Long An, Tiền Giang, Bến Tre, Trà Vinh, Vĩnh Long, Sóc Trăng, Bạc Liêu, Hậu Giang, Cà Mau và Kiên Giang.<br>Dự báo, có khoảng 332.000 ha lúa bị thiếu nước, khoảng 136.000ha cây ăn quả có khả năng bị ảnh hưởng. Riêng đối với nước sinh hoạt, dự báo trong thời gian tiếp theo của mùa khô, sẽ có khoảng 158.000 hộ thiếu nước sinh hoạt. Trong đó, tinh Tiền Giang và tỉnh Bến Tre sẽ là hai địa phương bị ảnh hưởng nặng nề nhất khi hạn hán và xâm nhập mặn xảy ra nghiêm trọng&quot;.<br>(Nguôn: Báo Nhân Dân)", "cauHoi": [{"question": "Vấn đề nghiêm trọng nhất mà các tỉnh Đồng bằng sông Cửu Long đang gặp phải trong mùa khô là", "choices": ["ngập lụt.", "nước biển dâng.", "ô nhiễm nguồn nước.", "hạn mặn."], "correctIndex": 3, "explain": "<b>Câu 112:</b> → <b>D. hạn mặn</b><br>→ Đoạn văn nhấn mạnh <b>hạn hán và xâm nhập mặn</b> gây ảnh hưởng trực tiếp đến cây trồng và nước sinh hoạt → đây là vấn đề nghiêm trọng nhất trong mùa khô."}, {"question": "Hai địa phương được dự báo sẽ có nguy cơ bị ảnh hưởng nặng nề nhất khi hạn hán và xâm nhập mặn xảy ra nghiêm trọng là", "choices": ["Tiền Giang và Bạc Liêu.", "Tiền Giang và Bến Tre.", "Vĩnh Long và Sóc Trăng.", "Cà Mau và Kiên Giang."], "correctIndex": 1, "explain": "<b>Câu 113:</b> → <b>B. Tiền Giang và Bến Tre</b><br>→ Văn bản nêu rõ đây là <b>hai địa phương bị ảnh hưởng nặng nề nhất</b>."}, {"question": "Giải pháp cấp bách nhất để giảm thiểu ảnh hưởng của tình trạng xâm nhập mặn và hạn hán ở đồng bằng sông Cửu Long là gì?", "choices": ["Áp dụng các biện pháp thủy lợi kịp thời và thích hợp.", "Sử dụng các giống cây chịu hạn, chịu mặn.", "Điều chỉnh mùa vụ, thay đổi cơ cấu cây trồng hợp lí.", "Tuyên truyền, hướng dẫn người dân sử dụng tiết kiệm, tích, trữ nước."], "correctIndex": 0, "explain": "<b>Câu 114:</b> → <b>A. Áp dụng các biện pháp thủy lợi kịp thời và thích hợp</b><br>→ Vì đây là <b>giải pháp cấp bách nhất</b> để ngăn mặn, trữ ngọt (đê, cống, kênh…), xử lý trực tiếp nguyên nhân."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>&quot;Ngày Chiến thắng cuộc Chiến tranh Bảo vệ Biên giới Tây Nam của Tổ quốc (7/1/19797/1/2024) là dịp để tưởng nhớ về sự hy sinh to lớn của các thế hệ cha anh đi trước cũng như sự mất mát, đau thưong của Nhân dân ta khi bị chế độ diệt chủng Pol Pot - Ieng Sary (còn gọi là Khmer Đỏ) ra tay thảm sát dã man, tiến hành cuộc chiến tranh xâm lược biên giới Tây Nam của Tổ quốc.<br>Chiến tranh Bảo vệ Biên giới Tây Nam là cuộc chiến tranh chính nghĩa, sự tự vệ chính đáng của dân tộc, nhằm bảo vệ độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ, thể hiện tinh thần đoàn kết quốc tế trong sáng, cao cả của dân tộc Việt Nam đối với nhân dân nước bạn Cam-pu-chia.&quot;", "cauHoi": [{"question": "Trong khoảng thời gian từ năm 1975 đến năm 1979, cuộc chiến đấu ở biên giới Tây Nam của quân dân Việt Nam thực hiện nhiệm vụ nào sau đây?", "choices": ["Đánh đổ phát xít.", "Đánh đổ phong kiến.", "Bảo vệ Tổ quốc.", "Giải phóng dân tộc."], "correctIndex": 2, "explain": "<b>Câu 115:</b> → <b>C. Bảo vệ Tổ quốc</b><br>→ Đây là cuộc chiến tranh <b>tự vệ chính nghĩa</b> nhằm bảo vệ chủ quyền lãnh thổ trước sự xâm lược từ bên ngoài, không phải đánh đổ hay giải phóng."}, {"question": "Sau khi lên nắm quyền (4/1975), tập đoàn Pôn Pốt - Iêng Xa-ri - Khiêu Xăm-phon đã có hành động nào sau đây?", "choices": ["Tiến hành công cuộc xây dựng chủ nghĩa xã hội trong cả nước.", "Tiến hành các hoạt động khiêu khích, lấn chiếm lãnh thổ Việt Nam.", "Ủng hộ, giúp đỡ công cuộc xây dựng đất nước Việt Nam.", "Liên kết với các nước Đông Nam Á để chống lại Trung Quốc."], "correctIndex": 1, "explain": "<b>Câu 116: → B. Tiến hành các hoạt động khiêu khích, lấn chiếm lãnh thổ Việt Nam</b><br>→ Sau khi lên nắm quyền, tập đoàn Khmer Đỏ (Pôn Pốt) đã liên tục <b>tấn công, xâm nhập biên giới Tây Nam</b> của Việt Nam."}, {"question": "Cuộc chiễn đấu bảo vệ Tổ quốc ở vùng biên giới Tây Nam thắng lợi đã", "choices": ["chấm dứt vĩnh viễn mọi cuộc chiến tranh từ thế lực ngoại xâm.", "chấm dứt mọi cuộc chiến tranh xâm lược từ Trung Quốc.", "mở đầu thời kì độc lập, tự chủ lâu dài cho dân tộc.", "làm tròn nghĩa vụ quốc tế đối với nhân dân Campuchia."], "correctIndex": 3, "explain": "<b>Câu 117:</b> → <b>D. Làm tròn nghĩa vụ quốc tế đối với nhân dân Campuchia</b><br>→ Việt Nam không chỉ bảo vệ mình mà còn <b>giúp nhân dân Campuchia thoát khỏi chế độ diệt chủng</b>, thể hiện tinh thần quốc tế."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>&quot;Luật Tư pháp người chưa thành niên có nhiệm vụ bảo vệ quyền, lợi ích tốt nhất cho người chưa thành niên; bảo đảm việc xử lý người chưa thành niên phù hợp với độ tuối, khả năng nhận thức, đặc điểm nhân thân, tính chất nguy hiểm cho xã hội của hành vi phạm tội; giáo dục, giúp đỡ người chưa thành niên tự sửa chữa sai lầm, cải thiện hành vi, trở thành công dân có ích cho xã hội.<br>Luật này quy định về xử lý chuyển hướng, hình phạt và thủ tục tố tụng đối với người chưa thành niên phạm tội; thủ tục tố tụng đối với bị hại và người làm chứng; thi hành án; tái hòa nhập cộng đồng và hỗ trợ bị hại; nhiệm vụ, quyền hạn và trách nhiệm của cơ quan, tổ chức, cá nhân trong hoạt động tư pháp người chưa thành niên.<br>Đáng chú ý, Luật quy định các biện pháp xử lý chuyển hướng gồm: Khiển trách; hạn chế khung giờ sinh hoạt, đi lại; xin lỗi người bị hại; bồi thường thiệt hại; tham gia chương trình học tập, dạy nghề; điều trị, tư vấn tâm lý bắt buộc; lao động công ích; cấm tiếp xúc; cấm đến một địa điểm nhất định; giáo dục tại xã, phường, thị trấn; giáo dục tại trường giáo dưỡng.&quot;<br>(Nguồn: Báo Đà Nẵng)", "cauHoi": [{"question": "Theo Luật Tư pháp người chưa thành niên, mục tiêu chính trong việc xử lý người chưa thành niên phạm tội là gì?", "choices": ["Xử lý nghiêm khắc để răn đe.", "Bảo vệ quyền và lợi ích tốt nhất cho người chưa thành niên.", "Đưa người chưa thành niên vào trại cải tạo.", "Xử lý theo cách thức giống như người trưởng thành."], "correctIndex": 1, "explain": "<b>Hướng dẫn: Đáp án: B</b><br>Giải thích: Đoạn văn nêu rõ mục tiêu của Luật Tư pháp người chưa thành niên là bảo vệ quyền lợi cho người chưa thành niên và giúp họ sửa chữa sai lầm, cải thiện hành vi để trớ thành công dân có ích."}, {"question": "Điều gì không được quy định trong các biện pháp xử lý chuyển hướng đối với người chưa thành niên phạm tội theo Luật Tư pháp người chưa thành niên?", "choices": ["Khiển trách và hạn chế khung giờ sinh hoạt.", "Bồi thường thiệt hại và tham gia chương trình học tập, dạy nghề.", "Cấm tiếp xúc và cấm đến một địa điểm nhất định.", "Tăng mức hình phạt theo độ tuổi."], "correctIndex": 3, "explain": "<b>Đáp án: D</b><br>Giải thích: Đoạn văn liệt kê các biện pháp xử lý chuyển hướng, nhưng không có đề cập đến việc tăng mức hình phạt theo độ tuổi của người chưa thành niên."}, {"question": "Theo Luật Tư pháp người chưa thành niên, biện pháp nào sau đây không phải là hình thức xử lý chuyển hướng đối với người chưa thành niên phạm tội?", "choices": ["Xin lỗi người bị hại.", "Điều trị, tư vấn tâm lý bắt buộc.", "Lao động công ích.", "Tống giam người chưa thành niên."], "correctIndex": 3, "explain": "<b>Đáp án: D</b><br>Giải thích: Đoạn văn liệt kê các biện pháp xử lý chuyển hướng đối với người chưa thành niên, trong đó không có biện pháp tống giam người chưa thành niên."}], "khongXaoTron": true}]};
